from pathlib import Path
for task in ('T02','T09'):
    path=Path('/workspace/ariadne-behavior-runs')/task/'response.md'
    lines=path.read_text(encoding='utf-8').splitlines(keepends=True)
    revised=[]
    in_display=False
    for line in lines:
        if line.strip() == r'\[':
            in_display=True
        if in_display or line.startswith('|'):
            revised.append(line)
        else:
            out=''
            depth=0
            for ch in line:
                if ch == '(':
                    if depth == 0:
                        out += r'\('
                    else:
                        out += ch
                    depth += 1
                elif ch == ')':
                    depth -= 1
                    out += r'\)' if depth == 0 else ch
                else:
                    out += ch
            revised.append(out)
        if line.strip() == r'\]':
            in_display=False
    path.write_text(''.join(revised), encoding='utf-8')
    print(f'{task}: repaired inline math delimiters')
PY
